const elements = await browserjs(tabBB, () => {
  // Find all elements containing "Apple - 11-inch iPad A16"
  const all = Array.from(document.querySelectorAll('*'));
  const matching = all.filter(el => el.children.length === 0 && el.innerText && el.innerText.includes('11-inch iPad A16'));
  return matching.map(el => {
    let parent = el;
    while (parent && parent !== document.body && !parent.querySelector('a[href*="/site/"]')) {
      parent = parent.parentElement;
    }
    const link = parent ? parent.querySelector('a[href*="/site/"]') : null;
    return {
      tag: el.tagName,
      text: el.innerText,
      parentTag: parent ? parent.tagName : null,
      parentClass: parent ? parent.className : null,
      href: link ? link.href : null,
      parentText: parent ? parent.innerText.slice(0, 300) : null
    };
  });
});

console.log("Matching elements:", JSON.stringify(elements, null, 2));

