const tabBB = 2136412423;

const blueItem = await browserjs(tabBB, () => {
  const links = Array.from(document.querySelectorAll('a')).filter(a => a.innerText && a.innerText.includes('11-inch iPad A16 chip with Wi-Fi - 128GB - Blue'));
  return links.map(a => {
    let container = a.closest('li') || a.parentElement;
    while (container && !container.innerText.includes('$449')) {
      container = container.parentElement;
    }
    return {
      text: a.innerText,
      href: a.href,
      containerHtml: container ? container.innerHTML.slice(0, 1500) : null,
      allLinks: container ? Array.from(container.querySelectorAll('a')).map(l => ({ text: l.innerText, href: l.href })) : []
    };
  });
});

console.log("Blue item details:", JSON.stringify(blueItem, null, 2));

