const tabAmz = 2136412425;

const results = await browserjs(tabAmz, () => {
  const items = Array.from(document.querySelectorAll('[data-component-type="s-search-result"]'));
  return items.map(item => {
    const titleEl = item.querySelector('h2 a span, h2 span');
    const linkEl = item.querySelector('h2 a');
    const priceWhole = item.querySelector('.a-price-whole')?.innerText?.trim();
    const priceFraction = item.querySelector('.a-price-fraction')?.innerText?.trim();
    const price = priceWhole ? `$${priceWhole}${priceFraction ? '.' + priceFraction : ''}` : null;
    const asin = item.getAttribute('data-asin');
    const title = titleEl?.innerText?.trim();
    const href = linkEl?.href;
    return { asin, title, price, href };
  }).filter(i => i.title);
});

console.log("Found", results.length, "results on Amazon");
console.log("First 15 results:", JSON.stringify(results.slice(0, 15), null, 2));

